import fs from 'node:fs/promises';
import { chromium } from 'playwright';
const ROOT='first-aid-medical-ifak';
const ROUTE='First Aid / Medical / IFAK';
const URL=`https://www.statesideqm.com/collections/${ROOT}?preview_theme_id=158561894555`;
const OUT=`cert-${ROOT}`;
const BAD=new Set(['all','stateside-quartermaster-logo-merch','air-national-guard-series','state-guard-series','rotc-series','jrotc-series','military-schools-academies','public-safety-series','army-national-guard-series']);
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const th=raw=>{try{return new URL(raw,'https://www.statesideqm.com').pathname.match(/^\/collections\/([^/?#]+)/)?.[1]||''}catch{return''}};
async function go(page){let r;for(let i=0;i<3;i++){r=await page.goto(URL,{waitUntil:'domcontentloaded',timeout:45000});if(r?.status()!==503)return r;await sleep(1500*(i+1))}return r}
async function check(page,mobile){
 const pageerrors=[];page.on('pageerror',e=>pageerrors.push(e.message));const r=await go(page);try{await page.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',{timeout:20000})}catch{}await sleep(2500);
 const d=await page.evaluate(()=>{const vis=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&r.width>0&&r.height>0};const m=document.querySelector('#MainContent'),side=m?.querySelector('.sq-refine-v3-sidebar'),size=m?.querySelector('.sq-refine-v3-page-size'),grid=m?.querySelector('.sq-refine-v3-results .product-grid'),groups=[...(side?.querySelectorAll('.sq-refine-v3-group')||[])];return{ready:m?.dataset.sqRefineV3Ready||'',active:m?.classList.contains('sq-refine-v3-active')||false,cleanup:m?.dataset.sqRefineV3RootCleanup||'',isolation:document.querySelector('[data-sq-refine-v3-legacy-isolation]')?.dataset.sqRefineV3LegacyIsolation||'',side:vis(side),sideTitle:side?.querySelector('.sq-refine-v3-sidebar__title')?.textContent.trim()||'',sidePos:side?getComputedStyle(side).position:'',sideHeight:side?.getBoundingClientRect().height||0,size:vis(size),sizeInSide:!!size?.closest('.sq-refine-v3-sidebar'),sizes:[...(size?.querySelectorAll('input')||[])].map(i=>[i.value,i.checked]),groups:groups.map(g=>({label:g.querySelector(':scope>summary')?.textContent.trim()||'',open:g.open,checked:g.querySelectorAll('input:checked').length,inputs:g.querySelectorAll('input[type="checkbox"]').length,targets:[...g.querySelectorAll('input[data-target]')].map(i=>i.dataset.target)})),grid:vis(grid),cols:grid?getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length:0,cards:grid?.querySelectorAll(':scope>.product-grid__item').length||0,legacy:[...document.querySelectorAll('[data-sq-refine-v3-hidden-nav="true"]')].filter(vis).length,globalLegacy:!!document.querySelector('.sq-global-refine-layout'),vac:[...document.querySelectorAll('.vac-page-size,[data-vac-page-size],[data-vac-page-view]')].filter(vis).length};});
 d.http=r?.status()||0;d.pageerrors=pageerrors;const e=[];if(d.http>=400)e.push('HTTP '+d.http);pageerrors.forEach(x=>e.push('pageerror '+x));if(d.ready!=='true'||!d.active)e.push('V3 not ready');if(d.cleanup!=='true'||d.isolation!==ROOT)e.push('V3 guards missing');if(!d.side||d.sideTitle!=='Refine Products')e.push('sidebar');if(!d.size||d.sizeInSide)e.push('page size placement');if(d.sizes.map(x=>x[0]).join(',')!=='50,100,250'||!d.sizes.find(x=>x[0]==='50')?.[1])e.push('page size values');const cat=d.groups.find(g=>/shop by category/i.test(g.label));if(!cat)e.push('category missing');else{const bad=cat.targets.map(th).filter(h=>BAD.has(h)&&h!==ROOT);if(bad.length)e.push('bad categories '+bad.join(','));}for(const g of d.groups){if(!g.inputs)e.push('empty '+g.label);if(!g.checked&&g.open)e.push('inactive open '+g.label);if(g.checked&&!g.open)e.push('active closed '+g.label)}if(d.globalLegacy)e.push('legacy global layout');if(d.legacy)e.push('legacy visible '+d.legacy);if(d.vac)e.push('old page size visible');if(!d.grid||d.cards!==50)e.push('grid/cards '+d.cards);if(d.grid&&d.cols!==(mobile?2:3))e.push('columns '+d.cols);if(mobile&&d.sidePos==='sticky')e.push('mobile sticky');if(!mobile&&(d.sidePos!=='sticky'||d.sideHeight<600))e.push('desktop sidebar');return{data:d,errors:e};
}
await fs.mkdir(OUT,{recursive:true});const b=await chromium.launch({headless:true}),report={route:ROUTE,root:ROOT};for(const [n,v,m] of [['desktop',{width:1440,height:1000},false],['mobile',{width:390,height:844},true]]){const c=await b.newContext({viewport:v}),p=await c.newPage();report[n]=await check(p,m);await p.screenshot({path:`${OUT}/${n}.png`,fullPage:true});await c.close()}await b.close();report.pass=!report.desktop.errors.length&&!report.mobile.errors.length;await fs.writeFile(`${OUT}/report.json`,JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));if(!report.pass)process.exitCode=1;
